Exact replication of newspaper-ending component. 9s, 1920x1080, SILENT. Newspaper paper texture background, career timeline with 5 milestones, recent photo reveal, final name lockup. GSAP controls all animation internally (not via external master timeline — use local timeline starting at t=0 to match the 49.5–58.5s window)
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=EB+Garamond:wght@400;700&display=swap" rel="stylesheet">
<style>
*,*:before,*:after{box-sizing:border-box;margin:0;padding:0;}
html,body{width:1920px;height:1080px;overflow:hidden;font-size:10px;}
newspaper-ending{
paper:#e6dfcf
paper-light:#f2ecdf
ink:#171816
muted:#686459
accent:#9f2026
position:absolute;inset:0;overflow:hidden
color:var(--ink)
background
repeating-linear-gradient(0deg,rgba(25,24,20,0.025) 0,rgba(25,24,20,0.025) 1px,transparent 1px,transparent 4px)
radial-gradient(circle at 20% 10%,var(--paper-light),var(--paper) 72%)
font-family:Arial,sans-serif
}
newspaper-ending::before{
content:"";position:absolute;inset:22px
border:1px solid rgba(23,24,22,0.32);pointer-events:none
}
/* MASTHEAD */
news-masthead{
position:absolute;top:50px;left:72px;right:72px;height:112px
display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:28px
border-top:5px solid var(--ink);border-bottom:2px solid var(--ink)
}
news-masthead>span{font-size:13px;font-weight:700;letter-spacing:0.2em;}
news-masthead>span:last-child{text-align:right;}
news-masthead>strong{
font-family:Georgia,"Times New Roman",serif
font-size:44px;line-height:1;letter-spacing:-0.035em;text-align:center
}
/* BODY */
newspaper-body{position:absolute;inset:180px 72px 50px;}
news-kicker{
margin:0;color:var(--accent);font-size:15px;font-weight:800;letter-spacing:0.22em
}
/* TIMELINE */
career-timeline{
position:absolute;left:0;right:0;top:94px;height:320px
display:grid;grid-template-columns:repeat(5,1fr);align-items:center
}
timeline-rule{
position:absolute;left:9%;right:9%;top:154px;height:3px
background:var(--ink);transform:scaleX(0);transform-origin:left center
}
timeline-rule::after{
content:"";position:absolute;left:0;bottom:-6px;width:100%;height:1px
background:rgba(23,24,22,0.35)
}
milestone{
position:relative;height:230px;padding-top:20px;text-align:center
opacity:0;transform:translateY(16px)
}
milestone::after{
content:"";position:absolute;left:50%;top:142px
width:15px;height:15px
border:3px solid var(--paper);border-radius:50%
background:var(--ink);transform:translateX(-50%)
box-shadow:0 0 0 2px var(--ink)
}
milestone time{
display:block;font-family:Georgia,"Times New Roman",serif
font-size:43px;font-weight:700;line-height:1
}
milestone strong{display:block;margin-top:14px;font-size:17px;letter-spacing:0.14em;}
milestone small{
display:block;max-width:170px;margin:68px auto 0
color:var(--muted);font-size:11px;font-weight:700;line-height:1.4;letter-spacing:0.12em
}
milestone-latest time,.milestone-latest strong{color:var(--accent);}
milestone-latest::after{background:var(--accent);box-shadow:0 0 0 2px var(--accent);}
/* RECENT PHOTO */
recent-proof{
position:absolute;top:6px;right:0;width:500px;margin:0;padding:11px
background:var(--paper-light);border:1px solid var(--ink)
box-shadow:14px 16px 0 rgba(23,24,22,0.12)
clip-path:inset(0 0 0 100%);opacity:0;z-index:4
}
recent-photo{height:390px;overflow:hidden;background:#aaa498;}
recent-photo img{
width:100%;height:100%;object-fit:cover;object-position:center top
filter:saturate(0.72) contrast(1.08);transform:scale(1.08)
}
recent-proof figcaption{
display:flex;justify-content:space-between;align-items:flex-end
gap:20px;padding:13px 4px 3px
}
recent-proof figcaption strong{font-family:Georgia,"Times New Roman",serif;font-size:18px;}
recent-proof figcaption span{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:0.12em;}
/* FOOTER */
news-footer{
position:absolute;left:0;right:0;bottom:12px
display:flex;justify-content:space-between;padding-top:12px
border-top:2px solid var(--ink);font-size:12px;font-weight:800;letter-spacing:0.24em
}
/* FINAL LOCKUP */
final-lockup{
position:absolute;inset:0;display:grid;place-content:center
text-align:center;opacity:0;visibility:hidden
}
final-lockup span{color:var(--accent);font-size:14px;font-weight:800;letter-spacing:0.3em;}
final-lockup h2{
margin:18px 0;font-family:Georgia,"Times New Roman",serif
font-size:92px;line-height:0.82;letter-spacing:-0.055em
}
final-lockup i{
display:block;width:480px;height:3px;margin:10px auto 18px
background:var(--ink);transform:scaleX(0)
}
final-lockup p{margin:0;font-size:16px;font-weight:800;letter-spacing:0.28em;}
#open-fade,#close-fade{position:absolute;inset:0;z-index:100;background:#000;pointer-events:none;}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="open-fade"></div>
<div id="close-fade"></div>
<section class="newspaper-ending">
<header class="news-masthead">
<span>THE ACTOR'S RECORD</span>
<strong>BENEDICT CUMBERBATCH</strong>
<span>LONDON · 2026</span>
</header>
<div class="newspaper-body">
<p class="news-kicker">A CAREER IN FIVE ACTS</p>
<div class="career-timeline">
<div class="timeline-rule"></div>
<article class="milestone"><time>2004</time><strong>HAWKING</strong><small>THE BREAKTHROUGH</small></article>
<article class="milestone"><time>2010</time><strong>SHERLOCK</strong><small>THE PHENOMENON</small></article>
<article class="milestone"><time>2014</time><strong>TURING</strong><small>THE IMITATION GAME</small></article>
<article class="milestone"><time>2015</time><strong>HAMLET</strong><small>RETURN TO THE STAGE</small></article>
<article class="milestone milestone-latest"><time>2026</time><strong>EARTH</strong><small>STILL EVOLVING</small></article>
</div>
<figure class="recent-proof">
<div class="recent-photo"><img src="{{recentPhoto}}" alt="Benedict Cumberbatch 2026"></div>
<figcaption>
<strong>HOW TO LIVE ON EARTH</strong>
<span>Presenter · 2026</span>
</figcaption>
</figure>
<footer class="news-footer">
<span>STAGE</span><span>SCREEN</span><span>VOICE</span><span>LEGACY</span>
</footer>
</div>
<div class="final-lockup">
<span>THE STORY CONTINUES</span>
<h2>BENEDICT<br>CUMBERBATCH</h2>
<i></i>
<p>STILL EVOLVING</p>
</div>
</section>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded', function(){
/* local timeline — t=0 maps to scene start (49.5s in film) */
var tl = gsap.timeline()
/* open fade */
tl.to('#open-fade', {opacity:0, duration:0.4, ease:'power2.out'}, 0.0)
/* 0–0.8s : timeline rule draws (= film 49.5–50.3s) */
tl.to('.timeline-rule', {scaleX:1, duration:0.8, ease:'power3.inOut'}, 0.0)
/* 0.8–3.3s : five milestones stagger in (= 50.3–52.9s) */
tl.fromTo('.milestone'
{y:16, autoAlpha:0}
{y:0, autoAlpha:1, duration:0.42, stagger:0.48, ease:'power3.out'}
0.8
)
/* 3.3–7.3s : dim others, scale latest, reveal photo (= 52.9–56.8s) */
tl.to('.milestone:not(.milestone-latest)', {autoAlpha:0.22, duration:0.4}, 3.4)
tl.to('.milestone-latest', {scale:1.12, transformOrigin:'center center', duration:0.55, ease:'power3.out'}, 3.4)
tl.fromTo('.recent-proof'
{clipPath:'inset(0 0 0 100%)', autoAlpha:0}
{clipPath:'inset(0 0 0 0%)', autoAlpha:1, duration:0.72, ease:'power4.inOut'}
3.4
)
tl.to('.recent-photo img', {scale:1, duration:3.9, ease:'sine.inOut'}, 3.4)
/* 7.3–9s : final name lockup (= 56.8–58.5s) */
tl.to('.newspaper-body, .news-masthead', {autoAlpha:0, duration:0.38, ease:'power2.in'}, 7.3)
tl.fromTo('.final-lockup'
{y:22, autoAlpha:0}
{y:0, autoAlpha:1, duration:0.65, ease:'power4.out'
onStart:function(){ gsap.set('.final-lockup',{visibility:'visible'}); }}
7.45
)
tl.to('.final-lockup i', {scaleX:1, duration:0.55, ease:'power3.out'}, 7.75)
/* close */
tl.to('#close-fade', {opacity:1, duration:0.5, ease:'power2.inOut'}, 8.6)
tl.set('#close-fade', {opacity:1}, 9.0)
})
</script>
</body>
</html>
```
